// Web Application Firewall rules
@Component
public class SpelWafFilter implements Filter {

    private static final Map<String, Integer> THREAT_SCORES = Map.of(
        "T(", 100,          // Critical
        "Runtime", 90,      // Critical
        "exec", 85,         // Critical
        "ProcessBuilder", 85,
        "@", 50,            // Medium - could be legitimate bean reference
        "${", 50            // Medium - could be legitimate EL
    );

    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                        FilterChain chain) throws IOException, ServletException {

        HttpServletRequest httpRequest = (HttpServletRequest) request;
        String queryString = httpRequest.getQueryString();

        if (queryString != null) {
            int threatScore = calculateThreatScore(queryString);

            if (threatScore >= 100) {
                // Block immediately
                HttpServletResponse httpResponse = (HttpServletResponse) response;
                httpResponse.sendError(403, "Request blocked");
                return;
            } else if (threatScore >= 50) {
                // Log for investigation
                log.warn("Suspicious request with score {}: {}", threatScore, queryString);
            }
        }

        chain.doFilter(request, response);
    }

    private int calculateThreatScore(String input) {
        int score = 0;
        for (Map.Entry<String, Integer> entry : THREAT_SCORES.entrySet()) {
            if (input.contains(entry.getKey())) {
                score += entry.getValue();
            }
        }
        return score;
    }
}
```

